+    private Dialect getDialect(final JsonNode schemaNode, SchemaRegistryConfig config) {
+        final JsonNode iriNode = schemaNode.get("$schema");
+        if (iriNode != null && iriNode.isTextual()) {
+            return getDialect(iriNode.textValue());
+        }
+        return null;
