+            this.formatAssertionsEnabled = formatAssertionsEnabled;
+            return self();
+        }
+
+        public T javaSemantics(boolean javaSemantics) {
+            this.javaSemantics = javaSemantics;
+            return self();
+        }
+
+		/**
+		 * Set the locale to consider when generating localized messages.
